package com.medicore.order.client; import com.medicore.order.dto.*; import org.springframework.cloud.openfeign.FeignClient; import org.springframework.web.bind.annotation.*; @FeignClient(name="${inventory.service.name:inventory-service}") public interface InventoryClient {@PostMapping("/api/inventory/{medicineId}/reserve") InventoryReservationResponse reserve(@PathVariable Long medicineId,@RequestBody InventoryReservationRequest request); @PostMapping("/api/inventory/{medicineId}/release") void release(@PathVariable Long medicineId,@RequestBody InventoryReservationRequest request);}
